// Writes .htaccess for Apache/LiteSpeed static hosting (Hostinger). Usage: node scripts/write-htaccess.mjs <dir> <preview|release>
import { writeFileSync } from "node:fs";
import { join } from "node:path";
export function htaccess(mode) {
  return [
    "# Generated by scripts/write-htaccess.mjs, do not edit by hand.",
    "Options -Indexes -MultiViews",
    "DirectoryIndex index.html",
    "ErrorDocument 404 /404.html",
    "DirectorySlash On",
    "<IfModule mod_rewrite.c>",
    "  RewriteEngine On",
    "  RewriteCond %{HTTPS} !=on",
    "  RewriteCond %{HTTP:X-Forwarded-Proto} !https",
    "  RewriteRule ^ https://%{HTTP_HOST}%{REQUEST_URI} [L,R=301]",
    "  # Legacy redirects are added here from docs/URL-MAP.csv once approved.",
    "</IfModule>",
    "<IfModule mod_headers.c>",
    mode === "preview" ? '  Header always set X-Robots-Tag "noindex, nofollow"' : "  # Release: indexable.",
    '  Header always set X-Content-Type-Options "nosniff"',
    '  Header always set Referrer-Policy "strict-origin-when-cross-origin"',
    '  <FilesMatch "\\.(html|xml|txt)$">',
    '    Header set Cache-Control "no-cache"',
    "  </FilesMatch>",
    "</IfModule>",
    "<IfModule mod_expires.c>",
    "  ExpiresActive On",
    '  <FilesMatch "\\.(css|js|woff2|svg|png|webp|jpg)$">',
    "    ExpiresDefault \"access plus 1 year\"",
    "  </FilesMatch>",
    "</IfModule>",
    "",
  ].join("\n");
}
if (import.meta.url === `file://${process.argv[1]}`) {
  const [dir = "dist", mode = "preview"] = process.argv.slice(2);
  writeFileSync(join(dir, ".htaccess"), htaccess(mode));
  console.log(`wrote ${dir}/.htaccess (${mode})`);
}
